    {
      "keystrokes": "dd if=/dev/zero of=/app/test.bin bs=1M count=200 2>&1; echo EXIT=$?; df -h /; ls -la /app/test.bin\n",
      "duration": 3.0
    },
    {
      "keystrokes": "rm -f /app/test.bin; du -sh /var/lib/apt/lists 2>/dev/null\n",
      "duration": 0.5
    },
    {
      "keystrokes": "mount | grep -E 'shm| /run '; cat /proc/mounts | grep -E ' /run |/dev/shm'\n",
      "duration": 0.1
    }
  ]
